import{_ as d,o as e,c as a,ag as o}from"./chunks/framework.C5oN-8Wt.js";const m=JSON.parse('{"title":"复数高通滤波器","description":"","frontmatter":{},"headers":[],"relativePath":"v0.2.0-alpha/modules/complex_high_pass/index.md","filePath":"v0.2.0-alpha/modules/complex_high_pass/index.md"}'),c={name:"v0.2.0-alpha/modules/complex_high_pass/index.md"};function r(n,t,l,i,h,p){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="复数高通滤波器" tabindex="-1">复数高通滤波器 <a class="header-anchor" href="#复数高通滤波器" aria-label="Permalink to &quot;复数高通滤波器&quot;">​</a></h1><p>适用：v0.2.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>complex_high_pass</code> · 模块定义版本：4</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>衰减复数信号零频率附近的成分，保留较大的正、负频率。适合去除复数直流偏置，并观察复数高通与低通的互补选频方向。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p><code>复数混合信号.out → 复数高通滤波器.in</code>。另分支进入复数低通，在观察器中比较两种输出的 I/Q 和双边频谱。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输入</td><td><code>in</code>（输入）</td><td><code>complex_f64</code></td><td>归一化幅度；vlen=1</td></tr><tr><td>输出</td><td><code>out</code>（输出）</td><td><code>complex_f64</code></td><td>归一化幅度；vlen=1</td></tr></tbody></table><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p>这里的“高”指离零频率更远，不是只保留正频率。输入采样率、截止和过渡带要一起设置；复数数据类型本身不会让错误的采样率变正确。</p><p>实系数抽头同时处理 I 与 Q。若再抽取，保留的高频可能超过新 Nyquist 范围，因此高通后降采样需要特别检查实际带宽。</p><p><code>window_param</code> 随设计窗解释：Kaiser 使用 β（≥ 0）；Exponential 使用半窗长度上的衰减 d（dB，≥ 0）；Gaussian 使用 σ（&gt; 0）；Tukey 使用 α（0 ≤ α ≤ 1）。这个参数只对相应四种窗有意义，其他窗不靠它改变。切换窗后按新的含义检查数值，尤其不能给 Tukey 沿用超出 0 到 1 的旧值。</p><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>输入采样率 (Hz)<br><code>sample_rate_hz</code></td><td><code>4096</code></td><td>范围 5e-324 至 1000000；须等于上游实际采样率，可低于 1 Hz。插值滤波按输出采样率设计抽头。</td><td>重新准备</td></tr><tr><td>截止频率 (Hz)<br><code>cutoff_hz</code></td><td><code>512</code></td><td>范围 0 至 500000；须小于设计采样率的一半；插值时设计采样率为输入率乘插值倍数。</td><td>可在线应用</td></tr><tr><td>过渡带宽 (Hz)<br><code>transition_hz</code></td><td><code>128</code></td><td>范围 0 至 500000；须小于设计采样率的一半；插值时设计采样率为输入率乘插值倍数。</td><td>可在线应用</td></tr><tr><td>通带增益<br><code>gain</code></td><td><code>1</code></td><td>范围 -3.4028234663852886e+38 至 3.4028234663852886e+38</td><td>可在线应用</td></tr><tr><td>设计窗函数<br><code>window</code></td><td><code>hamming</code></td><td>Hamming (<code>hamming</code>)；Hann (<code>hann</code>)；Blackman (<code>blackman</code>)；Rectangular (<code>rectangular</code>)；Kaiser (<code>kaiser</code>)；Blackman-Harris (<code>blackman_harris</code>)；Bartlett (<code>bartlett</code>)；Flat top (<code>flattop</code>)；Nuttall (<code>nuttall</code>)；Nuttall CFD (<code>nuttall_cfd</code>)；Welch (<code>welch</code>)；Parzen (<code>parzen</code>)；Exponential (<code>exponential</code>)；Riemann (<code>riemann</code>)；Gaussian (<code>gaussian</code>)；Tukey (<code>tukey</code>)</td><td>可在线应用</td></tr><tr><td>窗参数<br><code>window_param</code></td><td><code>6.76</code></td><td>范围 0 至 3.4028234663852886e+38</td><td>可在线应用</td></tr><tr><td>抽取倍数<br><code>decimation</code></td><td><code>1</code></td><td>范围 1 至 1024；当前产品支持 1–1024，抽取和插值中最多一个大于 1；修改后须重新准备。</td><td>重新准备</td></tr><tr><td>插值倍数<br><code>interpolation</code></td><td><code>1</code></td><td>范围 1 至 1024；当前产品支持 1–1024，抽取和插值中最多一个大于 1；修改后须重新准备。</td><td>重新准备</td></tr></tbody></table><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>运行中可在线应用以下字段组；同组字段一起提交：</p><ul><li><code>gain</code>、<code>transition_hz</code>、<code>window</code>、<code>window_param</code>、<code>cutoff_hz</code></li></ul><p>其余计算字段需停止并重新准备。在线应用以该节点实际回执为准；编辑草稿本身不会改变已运行的图，旧缓存仍可能包含修改前的数据。</p><p>设计设置成组在线应用，抽头扩展受当前准备容量限制。速率变化需要重新准备，观察时区分启动过渡、修改附近样本和稳定输出。</p><h2 id="下载与观察" tabindex="-1">下载与观察 <a class="header-anchor" href="#下载与观察" aria-label="Permalink to &quot;下载与观察&quot;">​</a></h2><h3 id="复数处理与-i-q-往返" tabindex="-1">复数处理与 I/Q 往返 <a class="header-anchor" href="#复数处理与-i-q-往返" aria-label="Permalink to &quot;复数处理与 I/Q 往返&quot;">​</a></h3><p><a href="../../../downloads/v0.2.0-alpha/complex-iq.cnsproj" download>下载 complex-iq.cnsproj</a></p><p>在 PC 上打开工程，按 F5 运行。有限运行可将参考源样本数设为 2048 item；重新打开工程后需再次运行以取得数据。</p><p>复数处理与 I/Q 往返</p><ul><li>观察复数旋转相量、乘 j 的相位变化及 I/Q 分解再合成；复数频谱保留正负频率。</li></ul><p>复数处理示例让同一个混合输出分别进入高通与其他滤波分支。高通预期保留 768 Hz 相量、衰减 64 Hz 相量。用频谱确认频率，不只根据时域曲线的疏密判断。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>负频率为什么还在？</strong> 实系数高通对正负频率具有相应选频响应，不是正频率选择器。</p><p><strong>偏置去掉后，起始处仍有波动？</strong> 滤波器需要建立输入历史，先查看稳定段再讨论直流抑制。</p>',29)])])}const u=d(c,[["render",r]]);export{m as __pageData,u as default};
